tool_input.command:
set -e; T=/tmp/c223; S=/home/runner/czaba-project/store
for v in s1mut s1ctl; do rm -rf $T/$v; mkdir -p $T/$v; cp -r $S/perf $T/$v/perf; ln -sfn $S/node_modules $T/$v/node_modules
cat > $T/$v/playwright.perf.config.ts <<'EOF'
import { defineConfig, devices } from '@playwright/test';
export default defineConfig({
  testDir: './perf', testMatch: 'studio-lab-resources.perf.spec.ts', workers: 1, retries: 0, timeout: 15 * 60 * 1000,
  reporter: [['list']], outputDir: './test-results/perf-artifacts',
  use: { baseURL: 'http://127.0.0.1:5188', trace: 'off' },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'], viewport: { width: 1440, height: 900 }, launchOptions: { args: ['--autoplay-policy=no-user-gesture-required'] } } }],
});
EOF
f=$T/$v/perf/studio-lab-resources.perf.spec.ts
python3 - "$f" "$v" <<'EOF'
import sys
p,v=sys.argv[1],sys.argv[2]; s=open(p).read()
old="""      const text = document.querySelector('[role="dialog"]')?.textContent ?? '';
      if (!text.includes('WAV created:')) return;"""
assert s.count(old)==1; s=s.replace(old,old.replace("'WAV created:'","'WAV NEVER C223:'"))
s=s.replace("const cpuRates = [1, 6];","const cpuRates = [1];",1).replace("const passesPerRate = 3;","const passesPerRate = 1;",1)
anchor="""    if (!released) {
      result.problems.push(`export ${clips}: the "WAV created" observer was not released`);
    }"""
assert s.count(anchor)==1
s=s.replace(anchor,anchor+"""
    console.log('S1PROBE', clips, 'released=' + released, 'handleClearedAfter=' + (await page.evaluate(() => window.__czabaExportObserver === undefined)), 't1=' + t1);""")
if v=='s1ctl':
    rm="""        window.__czabaExportObserver = undefined;
        observer?.disconnect();
"""
    assert s.count(rm)==1; s=s.replace(rm,"")
open(p,'w').write(s)
EOF
done; diff $T/s1mut/perf/studio-lab-resources.perf.spec.ts $T/s1ctl/perf/studio-lab-resources.perf.spec.ts; diff $S/perf/studio-lab-resources.perf.spec.ts $T/s1mut/perf/studio-lab-resources.perf.spec.ts | head -30
